<script setup>
import {reactive,ref,watch} from 'vue'
import {onShow,onHide,onUnload} from '@dcloudio/uni-app'
import {ownerSession,clearOwnerSession} from '../../services/owner-session.js'
import {createDiagnosisRecovery} from '../../services/diagnosis-recovery.js'
import {vehicleApi} from '../../services/vehicles.js'
import {createAsyncDiagnosisApi,initialDiagnosisState,createAsyncDiagnosisFlow,SERVICE_STATES,CASE_STATES,validDiagnosisText} from '../../services/async-diagnosis.js'
import {imageRequestKey} from '../../services/private-images.js'
import {displayTime} from '../../services/reservations.js'
const state=reactive(initialDiagnosisState()),form=reactive({vehicle:0,text:'',consent:false}),vehiclePage=ref(1),api=createAsyncDiagnosisApi(),vehicles=vehicleApi,token=()=>ownerSession.accessToken
const recovery=createDiagnosisRecovery({actor:()=>ownerSession.actorId,role:()=> 'owner',scope:()=> 'diagnosis-owner'})
const flow=createAsyncDiagnosisFlow({state,token,recovery,scope:()=> 'diagnosis-owner',newKey:imageRequestKey,load:async(t,p)=>{const [context,cases,cars]=await Promise.all([api.context(t),api.list(t,'owner',p),vehicles.list(t,vehiclePage.value)]);return {context,cases,cars}},write:(t,a,id,b,k)=>api.write(t,'owner',a,id,b,k),confirm:()=>new Promise(resolve=>uni.showModal({title:'提交非实时人工诊断',content:'仅向获派诊断人员共享本次文字和所选车型，不共享历史档案。提交时重新核对当月资格和受理规则，不代表实时接单。确认后原请求将保存在当前设备，用于断线后原键恢复。',success:r=>resolve(r.confirm),fail:()=>resolve(false)})),onWritten:r=>{clearForm();uni.navigateTo({url:`/pages/diagnosis/detail?role=owner&id=${r.case_id}`})}})
let visible=false;function clearForm(){Object.assign(form,{vehicle:0,text:'',consent:false})}function reset(){flow.reset();clearForm()}
function login(){clearOwnerSession();uni.navigateTo({url:'/pages/owner/index'})}
function send(){const p=state.data?.context.service.policy;if(!state.data?.context.eligibility.service_available||!state.data.cars.items.some(v=>v.vehicle_id===form.vehicle)||!validDiagnosisText(form.text.trim())||!form.consent||!p){state.message='请核对当前资格、选择本人车辆、填写留言并确认用途。';return}flow.save('create',0,{vehicle_id:form.vehicle,policy_id:p.id,policy_revision:p.revision,message:form.text.trim(),consent:true})}
function restoreDraft(){const draft=flow.restoreDraft();if(draft){form.text=draft.text;form.vehicle=state.data.cars.items.some(v=>v.vehicle_id===draft.vehicle)?draft.vehicle:0;form.consent=false}}
function carsPage(p){vehiclePage.value=p;form.vehicle=0;flow.load(state.page)}
watch(token,()=>{reset();vehiclePage.value=1;if(visible&&token())flow.load()},{flush:'sync'})
onShow(()=>{visible=true;if(token())flow.load()});onHide(()=>{visible=false;reset()});onUnload(()=>{visible=false;reset()})
watch(()=>state.kind,k=>{if(['unauthorized','forbidden','missing'].includes(k)){clearForm()}})
</script>
<template><view class="reservation-page"><text class="reservation-title">非实时人工诊断</text><button @tap="uni.navigateTo({url:'/pages/diagnosis/notifications?role=owner'})">诊断站内消息</button><text>提交留言后等待获派诊断人员处理，可在此查看回复；不承诺即时在线。</text><button v-if="!token()" @tap="login">车主登录</button><text v-if="state.busy">正在核对…</text><text v-if="state.message">{{state.message}}</text><button v-if="['unauthorized','forbidden'].includes(state.kind)" @tap="login">重新登录</button><button v-if="state.retry" :disabled="state.busy" @tap="flow.retry">重试原提交</button><button :disabled="state.busy" @tap="flow.load(state.page)">刷新</button><template v-if="state.data"><view class="reservation-panel"><text>{{SERVICE_STATES[state.data.context.service.state]}}</text><text v-if="state.data.context.service.policy">{{state.data.context.service.policy.source_note}}</text><text>{{state.data.context.eligibility.month}} · 当前有效新客 {{state.data.context.eligibility.qualified_count}} 人</text><text v-if="!state.data.context.eligibility.service_available">当前不能新增留言；仍可查看本人已有问题与答复。</text><template v-else><text>选择本次车辆</text><button v-for="v in state.data.cars.items" :key="v.vehicle_id" :disabled="state.busy||state.retry" @tap="form.vehicle=v.vehicle_id">{{form.vehicle===v.vehicle_id?'已选择 · ':''}}{{v.model_name}} {{v.plate_no_masked}}</button><text v-if="!state.data.cars.items.length">暂无本人车辆，请先完成录车。</text><button v-if="vehiclePage>1" :disabled="state.busy||state.retry" @tap="carsPage(vehiclePage-1)">上一页车辆</button><button v-if="vehiclePage*20<state.data.cars.total" :disabled="state.busy||state.retry" @tap="carsPage(vehiclePage+1)">下一页车辆</button><text>草稿仅保存在当前设备；共享设备使用后请清除。</text><button :disabled="state.busy||state.retry" @tap="flow.saveDraft({text:form.text,vehicle:form.vehicle})">保存本机草稿</button><button v-if="state.hasDraft" :disabled="state.busy||state.retry" @tap="restoreDraft">恢复本机草稿</button><button v-if="state.hasDraft" :disabled="state.busy" @tap="flow.clearDraft">清除本机草稿</button><textarea v-model="form.text" maxlength="4000" :disabled="state.busy||state.retry" placeholder="本次车辆问题（最多2000字）"/><checkbox-group @change="form.consent=$event.detail.value.includes('yes')"><label><checkbox value="yes" :checked="form.consent" :disabled="state.busy||state.retry"/>确认将本次文字与车型用于人工诊断</label></checkbox-group><button :disabled="state.busy||state.retry" @tap="send">提交留言</button></template></view><text class="reservation-heading">本人诊断记录</text><text v-if="!state.data.cases.items.length">暂无诊断记录。</text><view v-for="c in state.data.cases.items" :key="c.case_id" class="reservation-panel"><text>{{CASE_STATES[c.status]}} · {{displayTime(c.updated_at)}}</text><button @tap="uni.navigateTo({url:`/pages/diagnosis/detail?role=owner&id=${c.case_id}`})">查看问题和答复</button></view><button v-if="state.page>1" :disabled="state.busy" @tap="flow.load(state.page-1)">上一页记录</button><button v-if="state.page*20<state.data.cases.total" :disabled="state.busy" @tap="flow.load(state.page+1)">下一页记录</button></template></view></template>
